import { registerMvuSchema } from 'https://testingcf.jsdelivr.net/gh/StageDog/tavern_resource/dist/util/mvu_zod.js';

export const Schema = z.object({
  创世权限系统: z.object({
    历史总源点: z.coerce.number().prefault(0),
    可用创世源点: z.coerce.number().prefault(0),
    当前权限等级: z.enum(['新手级', '合格级', '专家级', '最高权限']).prefault('新手级'),
  }).prefault({}),
  当前场景: z.object({
    所在世界ID: z.string().prefault('World_0'),
    具体时间: z.string().prefault('待初始化'),
    详细地点: z.string().prefault('待初始化'),
    周围环境: z.string().prefault('待初始化'),
  }).prefault({}),
  关键实体库: z.record(
    z.string().describe('实体名称'),
    z.object({
      实体类型: z.enum(['创世化身', '使者', '管理员', '具现实体', '外来者', '观测锚点']),
      所在世界ID: z.string().prefault('未知'),
      基础属性: z.object({
        种族与性别: z.string().prefault('未知'),
        外貌与特征: z.string().prefault('未知'),
        生命与存在状态: z.string().prefault('存活'),
        观念与性格: z.record(z.string().describe('标签'), z.boolean().describe('是否具备')).prefault({}),
        绝对能级评估: z.string().prefault('未知'),
      }).prefault({}),
      身份与称号: z.record(z.string().describe('称号名称'), z.string().describe('称号描述')).prefault({}),
      能力与法术: z.record(z.string().describe('能力名称'), z.string().describe('能力描述')).prefault({}),
      装备与持有物: z.record(z.string().describe('装备名称'), z.string().describe('装备描述')).prefault({}),
      当前动态: z.object({
        综合概述: z.string().prefault('无'),
        所在地: z.string().prefault('未知'),
        当前行动: z.string().prefault('无'),
        想法与目标: z.string().prefault('无'),
      }).prefault({}),
      人际关系: z.record(z.string().describe('关系人名'), z.string().describe('关系描述')).prefault({}),
      权限与账户: z.object({
        专属源点余额: z.coerce.number().prefault(0),
        使用限制: z.string().prefault('无限制'),
        认知权限: z.string().prefault('未知'),
      }).prefault({}),
    })
  ).prefault({}),
  世界列表: z.record(
    z.string().describe('世界ID'),
    z.object({
      世界名称: z.string().prefault('未知世界'),
      底层规则: z.string().prefault('未知规则'),
      时间流速比: z.coerce.number().prefault(1),
      宏观纪元: z.string().prefault('未知纪元'),
      核心势力与文明状态: z.record(z.string().describe('势力名称'), z.string().describe('状态描述')).prefault({}),
      全局变动记录: z.record(z.string().describe('变动事件'), z.string().describe('结算描述'))
        .transform(data => _(data).entries().takeRight(5).fromPairs().value())
        .prefault({}),
    })
  ).prefault({})
});

$(() => {
  registerMvuSchema(Schema);
})

