  <script type="module">
    /* 工具函数：渲染字典为HTML */
    function renderDict(dictObj, emptyText = '无') {
      if (!dictObj || Object.keys(dictObj).length === 0) return `<div class="dict-val">${emptyText}</div>`;
      let html = '';
      for (const [k, v] of Object.entries(dictObj)) {
        /* 布尔值转换 */
        const valStr = typeof v === 'boolean' ? (v ? '是' : '否') : v;
        html += `<div class="dict-row"><span class="dict-key">[${k}]</span> <span class="dict-val">${valStr}</span></div>`;
      }
      return html;
    }

    function populateCharacterData() {
      const all_variables = getAllVariables();

      /* 1. 创世权限系统 */
      const sys = _.get(all_variables, 'stat_data.创世权限系统', {});
      $('#val-total-point').text(sys.历史总源点 || 0);
      $('#val-current-point').text(sys.可用创世源点 || 0);
      $('#val-auth-level').text(sys.当前权限等级 || '未知');

      /* 2. 当前场景 */
      const scene = _.get(all_variables, 'stat_data.当前场景', {});
      $('#val-scene-world').text(scene.所在世界ID || '未知');
      $('#val-scene-time').text(scene.具体时间 || '未知');
      $('#val-scene-location').text(scene.详细地点 || '未知');
      $('#val-scene-env').text(scene.周围环境 || '未知');

      /* 3. 关键实体库 */
      const entities = _.get(all_variables, 'stat_data.关键实体库', {});
      let entityHtml = '';
      if (Object.keys(entities).length === 0) {
        entityHtml = '<div style="text-align:center; color:#666; padding:10px;">当前无观测实体</div>';
      } else {
        for (const [name, data] of Object.entries(entities)) {
          const attrs = data.基础属性 || {};
          const dyn = data.当前动态 || {};
          const acc = data.权限与账户 || {};

          entityHtml += `
            <div class="accordion-item">
              <div class="accordion-header">
                <span>${name}</span>
                <span class="entity-type">${data.实体类型 || '未知'}</span>
              </div>
              <div class="accordion-body">
                <div class="data-row"><span class="label">所在世界</span><span class="value">${data.所在世界ID || '未知'}</span></div>
                <div class="data-row"><span class="label">种族性别</span><span class="value">${attrs.种族与性别 || '未知'}</span></div>
                <div class="data-row"><span class="label">生命状态</span><span class="value">${attrs.生命与存在状态 || '未知'}</span></div>
                <div class="data-row"><span class="label">绝对能级</span><span class="value highlight">${attrs.绝对能级评估 || '未知'}</span></div>

                <div style="margin-top:8px; color:#888; font-size:12px;">当前动态：</div>
                <div class="dict-box">
                  <div class="dict-val">${dyn.综合概述 || '无'}</div>
                  <div class="dict-val">📍 ${dyn.所在地 || '未知'}</div>
                  <div class="dict-val">⚡ ${dyn.当前行动 || '无'}</div>
                  <div class="dict-val">💭 ${dyn.想法与目标 || '无'}</div>
                </div>

                <div style="margin-top:8px; color:#888; font-size:12px;">观念与性格：</div>
                <div class="dict-box">${renderDict(attrs.观念与性格)}</div>

                <div style="margin-top:8px; color:#888; font-size:12px;">身份与称号：</div>
                <div class="dict-box">${renderDict(data.身份与称号)}</div>

                <div style="margin-top:8px; color:#888; font-size:12px;">能力与法术：</div>
                <div class="dict-box">${renderDict(data.能力与法术)}</div>

                <div style="margin-top:8px; color:#888; font-size:12px;">专属账户：</div>
                <div class="dict-box">
                  <div class="dict-val">源点余额: <span style="color:#00d8ff">${acc.专属源点余额 || 0}</span></div>
                  <div class="dict-val">限制: ${acc.使用限制 || '无'}</div>
                </div>
              </div>
            </div>
          `;
        }
      }
      $('#entity-container').html(entityHtml);

      /* 4. 世界列表 */
      const worlds = _.get(all_variables, 'stat_data.世界列表', {});
      let worldHtml = '';
      if (Object.keys(worlds).length === 0) {
        worldHtml = '<div style="text-align:center; color:#666; padding:10px;">当前无沙盒世界</div>';
      } else {
        for (const [wid, data] of Object.entries(worlds)) {
          worldHtml += `
            <div class="accordion-item">
              <div class="accordion-header">
                <span>${data.世界名称 || wid}</span>
                <span class="entity-type">x ${data.时间流速比 || 1}倍</span>
              </div>
              <div class="accordion-body">
                <div class="data-row"><span class="label">世界ID</span><span class="value">${wid}</span></div>
                <div class="data-row"><span class="label">底层规则</span><span class="value">${data.底层规则 || '未知'}</span></div>
                <div class="data-row"><span class="label">宏观纪元</span><span class="value highlight">${data.宏观纪元 || '未知'}</span></div>

                <div style="margin-top:8px; color:#888; font-size:12px;">核心势力与状态：</div>
                <div class="dict-box">${renderDict(data.核心势力与文明状态, '暂无势力记录')}</div>

                <div style="margin-top:8px; color:#888; font-size:12px;">近期变动记录：</div>
                <div class="dict-box">${renderDict(data.全局变动记录, '近期风平浪静')}</div>
              </div>
            </div>
          `;
        }
      }
      $('#world-container').html(worldHtml);

      /* 重新绑定手风琴事件 */
      bindAccordion();
    }

    /* 绑定折叠面板事件 */
    function bindAccordion() {
      $('.accordion-header').off('click').on('click', function() {
        const body = $(this).next('.accordion-body');
        /* 切换显示状态 */
        body.slideToggle(200);
      });
    }

    async function init() {
      await waitGlobalInitialized('Mvu');
      populateCharacterData();

      /* 监听变量更新 */
      eventOn(Mvu.events.VARIABLE_UPDATE_ENDED, () => {
        populateCharacterData();
      });

      /* 标签切换逻辑 */
      $('.tab-btn').on('click', function() {
        const targetId = $(this).data('target');

        $('.tab-btn').removeClass('active');
        $(this).addClass('active');

        $('.tab-content').removeClass('active');
        $('#' + targetId).addClass('active');
      });
    }

    $(errorCatched(init));
  </script>
</head>
